# -*- coding: utf-8 -*-
from lib import *
import lib
def profile():
    # 东西向地形剖面（约北纬31.8°：地中海 → 耶路撒冷 → 死海 → 摩押高原），高度为示意
    pts = [(0,0),(60,0),(80,-20),(230,-60),(260,-120),(330,-260),(380,-330),(440,-560),(500,-700),(560,-760),(610,-720),(660,-520),(700,-280),(730,40),(760,90),(840,90),(860,40),(900,-300),(950,-640),(1000,-820),(1080,-860),(1160,-880)]
    base = 300; k = .22
    d = "M" + " ".join(f"{x},{base - y*k:.0f}" for x, y in [(p[0], -p[1]) for p in pts])
    d2 = d + " L1160,420 L0,420 Z"
    zones = [(30,"地中海","#5aa9ff"),(150,"沿海平原","#3ccf8e"),(300,"示非拉（低丘）","#f2c14e"),(520,"中央山地（犹大山地）","#ff9f43"),(790,"约旦河谷 · 死海","#2ed3c6"),(1060,"外约旦高原（摩押）","#a98bff")]
    o = ['<svg viewBox="0 0 1160 430" role="img" aria-label="迦南东西向地形剖面示意">',
         '<defs><linearGradient id="pf" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c9a46a"/><stop offset="1" stop-color="#6b4f2a"/></linearGradient></defs>',
         '<rect x="0" y="300" width="70" height="120" fill="#5aa9ff" opacity=".45"/>',
         f'<path d="{d2}" fill="url(#pf)" opacity=".9"/><path d="{d}" fill="none" stroke="#f2c14e" stroke-width="3"/>',
         '<line x1="0" y1="300" x2="1160" y2="300" stroke="#8c97b2" stroke-dasharray="6 6"/><text x="1150" y="294" text-anchor="end" font-size="13" class="tx">海平面 0 m</text>',
         '<rect x="740" y="318" width="110" height="10" fill="#2ed3c6" opacity=".8"/><text x="795" y="350" text-anchor="middle" font-size="14" font-weight="800">死海 约 −430 m（地表最低）</text>',
         '<circle cx="560" cy="133" r="7" fill="#ff6b5b"/><text x="560" y="118" text-anchor="middle" font-size="15" font-weight="800">耶路撒冷 约 750 m</text>',
         '<circle cx="1000" cy="120" r="7" fill="#a98bff"/><text x="1000" y="105" text-anchor="middle" font-size="15" font-weight="800">尼波山 约 800 m</text>']
    for x, t, c in zones:
        o.append(f'<text x="{x}" y="30" text-anchor="middle" font-size="15" font-weight="800" fill="{c}">{t}</text><line x1="{x}" y1="38" x2="{x}" y2="70" stroke="{c}" stroke-width="2"/>')
    o.append('<text x="580" y="415" text-anchor="middle" font-size="12" class="tx">西 ← 约 110 km（示意剖面，垂直比例夸大）→ 东</text></svg>')
    return '<div class="profile reveal"><div class="in">' + "".join(o) + '</div></div>'
def body():
    o = []
    o.append('''<section class="hero reveal"><div class="kick">PART 2 · HISTORY · GEOGRAPHY · CULTURE</div><h1>🗺️ 真实背景：三大帝国、列王与古近东先知文化</h1>
<p class="lead">先知书的舞台横跨约四百年（主前约800–430年），先后被三个帝国主宰：<span class="pl">亚述</span>（尼尼微）→ <span class="pl">巴比伦</span> → <span class="pl">波斯</span>（书珊）。以色列夹在<span class="pl">埃及</span>与<span class="pl">美索不达米亚</span>之间的“陆桥”上，每一次帝国更替都直接决定神百姓的命运。先知们宣告：<b class="k">这些帝国不过是神手中的器具</b>——“亚述是我怒气的棍”（赛10:5），“我的仆人巴比伦王尼布甲尼撒”（耶25:9），“古列是我的牧人”（赛44:28）。</p></section>''')
    o.append(H2("chrono", "⏳", "一、年代学：先知书的关键年份", "var(--blue)"))
    o.append(grid([card("锚点：主前763年日蚀", '<p>亚述名年官表记载布尔-萨加勒年的日蚀，天文学定为主前<span class="d">763年6月15日</span>，使亚述年表精确到年；阿摩司书8:9“使日头在午间落下”可能与此相关。</p>', "🌑", "var(--gold)"),
        card("王朝年表", '<p>列王纪的在位年数有<span class="h">共同执政</span>与<span class="h">登基年算法</span>的问题。本站采用 E. R. Thiele 式协调，并以亚述、巴比伦编年史为外部锚点。</p>', "🧮", "var(--purple)"),
        card("“七十年”", '<p>耶25:11；29:10。可从主前<span class="d">605</span>（第一次被掳）算到<span class="d">536/538</span>（归回），或从<span class="d">586</span>（圣殿被焚）算到<span class="d">516</span>（第二圣殿完工）——两种算法都约七十年（亚1:12；但9:2）。</p>', "7️⃣", "var(--teal)")], 290))
    o.append(table(["年代（主前，约）", "事件", "相关先知书", "外证锚点"], [
        ["793–753", "耶罗波安二世：北国最后的繁荣", "约拿、阿摩司、何西阿", "撒玛利亚陶片、象牙"], ["745", "提革拉毗列色三世即位，亚述扩张", "赛7–8；何5:13", "亚述年代记"],
        ["734–732", "叙利亚—以法莲战争；亚哈斯求助亚述", "赛7（以马内利）", "提革拉毗列色铭文提到“约哈斯（亚哈斯）”"], ["722", "撒玛利亚陷落，北国灭亡", "何、摩、弥1", "撒珥根二世铭文"],
        ["701", "西拿基立围耶路撒冷", "赛36–37；弥1", "泰勒棱柱、拉吉浮雕"], ["640–609", "约西亚在位，622年改革", "西番雅、耶利米早期", "—"],
        ["612", "尼尼微陷落", "那鸿", "巴比伦编年史"], ["605", "迦基米施之战；第一次被掳（但以理）", "耶46；但1；哈", "巴比伦编年史"],
        ["597", "约雅斤与以西结被掳", "结1:2", "巴比伦编年史：亚达月初二"], ["586", "耶路撒冷陷落，圣殿被焚", "耶39；52；哀；结33:21；俄", "拉吉书信"],
        ["539", "古列取巴比伦；伯沙撒被杀", "但5；赛45", "拿波尼度编年史"], ["538", "古列诏书", "拉1；赛44:28", "居鲁士圆柱"],
        ["520–516", "重建圣殿", "哈该、撒迦利亚", "贝希斯敦铭文（大流士一世）"], ["约460–430", "玛拉基；以斯拉、尼希米时期", "玛拉基", "象岛蒲草纸"]]))
    o.append(H2("empires", "🏰", "二、三大帝国与它们的君王", "var(--red)"))
    o.append(grid([card("🦁 新亚述帝国（约911–609）", '<p>首都<span class="pl">尼尼微</span>。以残酷著称：剥皮、穿刺、堆头颅，浮雕刻意展示恐怖。推行<b class="k">大规模迁民</b>政策。</p><ul><li><span class="pn">提革拉毗列色三世</span>（745–727）</li><li><span class="pn">撒缦以色五世</span>（727–722）</li><li><span class="pn">撒珥根二世</span>（722–705，赛20:1）</li><li><span class="pn">西拿基立</span>（705–681）</li><li><span class="pn">以撒哈顿</span>（681–669）</li><li><span class="pn">亚述巴尼帕</span>（669–约627，尼尼微图书馆）</li></ul>', "", "#ff6b5b"),
        card("🏛️ 新巴比伦帝国（626–539）", '<p>迦勒底王朝。首都<span class="pl">巴比伦</span>：伊施塔尔门、空中花园传说、马尔杜克神庙。掳掠各国的精英，在宫廷中培养（但1）。</p><ul><li><span class="pn">拿布坡拉撒</span>（626–605）</li><li><span class="pn">尼布甲尼撒二世</span>（605–562）</li><li><span class="pn">以未米罗达</span>（562–560，王下25:27）</li><li><span class="pn">拿波尼度</span>（556–539）与摄政王子<span class="pn">伯沙撒</span></li></ul>', "", "#a98bff"),
        card("👑 波斯帝国（550–330）", '<p>阿契美尼德王朝。首都<span class="pl">书珊</span>、<span class="pl">波斯波利斯</span>。行省制度、驿道、宽容的宗教政策：允许被掳民族归回、重建神庙。</p><ul><li><span class="pn">古列（居鲁士）</span>（559–530，539取巴比伦）</li><li><span class="pn">冈比西斯</span>（530–522）</li><li><span class="pn">大流士一世</span>（522–486，该1:1）</li><li><span class="pn">薛西一世 / 亚哈随鲁</span>（486–465）</li><li><span class="pn">亚达薛西一世</span>（465–424）</li></ul>', "", "#2ed3c6")], 300))
    o.append(KEY('<p>但以理书2章与7章的“四国”在历史中依次登场：巴比伦（金头 / 狮子）→ 玛代波斯（银 / 熊）→ 希腊（铜 / 豹）→ 罗马（铁 / 可怕的兽）。在第四国的时代，“非人手凿出来的石头”——<b class="xr">基督的国</b>——降临。</p>'))
    o.append(H2("kings", "👑", "三、先知 × 列王对照表", "var(--purple)"))
    o.append(table(["时期", "北国以色列", "南国犹大", "帝国", "先知"], [
        ["8世纪上半", "耶罗波安二世（793–753）", "乌西雅（792–740）", "亚述暂时衰弱", "约拿、阿摩司、何西阿"],
        ["8世纪下半", "比加、何细亚；722 亡国", "约坦、亚哈斯、希西家（715–686）", "提革拉毗列色三世 → 西拿基立", "以赛亚、弥迦、何西阿"],
        ["7世纪", "（已亡国）", "玛拿西（697–642）、亚们、约西亚（640–609）", "以撒哈顿、亚述巴尼帕；612 尼尼微亡", "那鸿、西番雅、耶利米（627 起）"],
        ["7世纪末–586", "—", "约哈斯、约雅敬、约雅斤、西底家", "尼布甲尼撒二世", "耶利米、哈巴谷、以西结、但以理"],
        ["被掳（586–539）", "—", "约雅斤在巴比伦（562 出监）", "以未米罗达 → 拿波尼度、伯沙撒", "以西结、但以理、（耶利米哀歌）、俄巴底亚"],
        ["归回（538–430）", "—", "所罗巴伯（省长）、大祭司约书亚", "古列 → 大流士一世 → 亚达薛西一世", "哈该、撒迦利亚、玛拉基"]]))
    o.append(H2("map", "🌍", "四、地图：迦南、亚述、巴比伦与波斯", "var(--orange)"))
    o.append('<p>以下地图采用真实经纬度绘制；圆点为城市，可对照经文中的地名。</p>')
    for m in ["land", "assyria", "babylon", "persia"]: o.append(lib.MAP(m))
    o.append(profile())
    o.append(BG('<p><b>地理与信息：</b>阿摩司来自<span class="pl">提哥亚</span>（伯利恒南方的旷野边缘），被差到北国的<span class="pl">伯特利</span>；约拿往西逃到<span class="pl">他施</span>（可能在今西班牙南部），而神差他往东去<span class="pl">尼尼微</span>；以西结在<span class="pl">迦巴鲁河边</span>（巴比伦尼普尔附近的运河）看见异象——<b class="k">神的荣耀不受地理限制</b>。</p>'))
    o.append(H2("culture", "🎭", "五、古近东的“先知”文化：相似与不同", "var(--teal)"))
    o.append(grid([
        card("马里的先知（约主前18世纪）", '<p>幼发拉底河畔马里城的书信记载“回应者”与“宣告者”向王传达神谕，也用“某神如此说”的格式。<b class="k">不同之处</b>：马里神谕多为王室利益与战争胜负，很少道德控诉；以色列的先知却敢于责备君王（撒下12；耶22）。</p>', "📜", "var(--gold)"),
        card("占卜与观兆", '<p>巴比伦有专业的占卜祭司：看羊肝、观星象、解梦。以西结书21:21 描写巴比伦王“摇签、求问神像、察看牺牲的肝”。但以理书2章的“术士、用法术的、行邪术的”正是这类专家——他们都失败了，<b class="k">唯有神能显明奥秘</b>（但2:28）。申18:10-15 禁止这一切，而应许一位像摩西的先知。</p>', "🔮", "var(--purple)"),
        card("亚述的宫廷先知", '<p>以撒哈顿时期的泥版保存了伊施塔尔女先知的神谕，常说“不要惧怕”。以赛亚书同样说“不要惧怕”（赛41:10），但发言者是<b class="k">创造天地的独一真神</b>，对象是被压迫的小民族，而不是帝国君王。</p>', "🏺", "var(--red)"),
        card("条约的咒诅", '<p>以撒哈顿继位条约（主前672年）列出大量咒诅：天如铜、地如铁、吃儿女的肉……与申28:23、53 惊人相似。先知引用的正是这种<b class="k">约的语言</b>：百姓背约，咒诅就要临到。</p>', "⚖️", "var(--teal)"),
        card("城市哀歌", '<p>苏美尔的《乌尔哀歌》哀悼城市被毁、城市的神离弃了它。耶利米哀歌用了相近的体裁，但承认<b class="k">是耶和华照约公义地审判</b>，并在废墟中宣告“他的怜悯不至断绝”（哀3:22）。</p>', "🕯️", "var(--blue)"),
        card("象征行动", '<p>先知常用“行动剧”：以赛亚赤身赤脚三年（赛20）、耶利米戴轭（耶27）、以西结侧卧390天（结4）、何西阿娶淫妇（何1）。这在口传文化中是极强的公共宣讲。</p>', "🎭", "var(--orange)"),
        card("8世纪的贫富悬殊", '<p>撒玛利亚出土的象牙饰板与“陶片”（油酒收据）显示精英阶层的奢华：阿摩司说“象牙床”“象牙的房屋”（摩3:15；6:4）；“马泽阿”（marzeah）宴会的饮酒狂欢（摩6:4-7）。先知的社会控诉有真实背景。</p>', "💎", "var(--pink)"),
        card("被掳者的生活", '<p>巴比伦“犹大城”（Al-Yahudu）出土的泥版显示：被掳者务农、经商、立契约、保存希伯来名字——正如耶利米劝他们“盖造房屋、栽种田园……为那城求平安”（耶29:5-7）。</p>', "🏠", "var(--green)")], 280))
    o.append(H2("arch", "🏺", "六、考古与外证：经文的真实历史处境", "var(--gold)"))
    o.append(table(["文物（主前，约）", "内容", "相关经文", "意义"], [
        ["撒珥根二世铭文（约710）", "撒珥根自称攻取撒玛利亚，迁走27,290人", "王下17；赛20:1", "撒珥根之名在圣经中只见于赛20:1，19世纪才被考古证实"],
        ["泰勒棱柱 / 西拿基立棱柱（约690）", "围困希西家“如笼中之鸟”，却未记攻陷", "赛36–37；王下18–19", "亚述自己也承认没有攻破耶路撒冷"],
        ["拉吉浮雕（约700）", "亚述攻陷拉吉的宫墙浮雕", "赛36:2；弥1:13", "古代最详细的围城图像之一"],
        ["西罗亚铭文（约701）", "希西家水道完工纪念", "赛22:9-11；王下20:20", "备战亚述"],
        ["巴比伦编年史", "605 迦基米施；597 攻取“犹大城”", "耶46:2；但1:1；结1:2", "精确到日的外证"],
        ["拉吉书信（约588）", "“看不见亚西加的烽火”", "耶34:7", "巴比伦围城末期"],
        ["约雅斤配给泥版", "巴比伦宫廷给“犹大王雅乌金”的油粮", "耶52:31-34", "被掳之君仍被保存——大卫的灯"],
        ["拿波尼度圆柱", "为长子<span class=pn>伯沙撒</span>祈福", "但5", "解释但5:7“第三位”：伯沙撒自己是第二位"],
        ["居鲁士圆柱（539后）", "古列让被掳民族归回、恢复神庙", "赛44:28；45:1；拉1", "波斯宗教政策"],
        ["贝希斯敦铭文（约520）", "大流士一世平定叛乱、即位", "该1:1；亚1:1", "哈该、撒迦利亚时期的背景"],
        ["象岛蒲草纸（约407）", "埃及犹太社群的书信，提到参巴拉之子", "玛拉基时期；尼2", "波斯时期犹太人的离散生活"],
        ["以赛亚大卷（1QIsaᵃ，约前125）", "死海古卷中完整的以赛亚书", "全卷以赛亚书", "比中世纪抄本早约一千年，内容高度一致"]]))
    o.append(KEY('<p>考古<b class="k">不是信心的根基</b>，圣经本身才是（BC 5）；但考古帮助我们看见：先知书写的是<b class="k">真实时间、真实地点里真实发生的事</b>。神在亚述、巴比伦、波斯的历史中说话，正如祂“在本丢·彼拉多手下”成就救恩。</p>'))
    o.append(cq("BC", 5, part="我们接受这些书卷，且只接受它们为圣经正典，用以规范、证实我们的信仰，作我们信仰的根基。"))
    return "".join(o)
